INSERT INTO `BaiDang` VALUES
(1,1,'Giới thiệu hệ thống chấm bài giải thuật','# 🚀 Giới thiệu hệ thống chấm bài\r\n\r\nChào mừng bạn đến với **hệ thống chấm bài giải thuật trực tuyến**.\r\n\r\n## 🎯 Mục tiêu\r\n- Luyện tập tư duy thuật toán\r\n- Chuẩn bị cho các kỳ thi lập trình\r\n- Nâng cao kỹ năng code thực tế\r\n\r\n## 🧠 Cách hoạt động\r\n1. Chọn bài tập\r\n2. Viết code\r\n3. Nộp bài\r\n4. Hệ thống tự động chấm và trả kết quả\r\n\r\n> 💡 Hãy bắt đầu từ các bài **Nhập Xuất Cơ Bản** nếu bạn là người mới!\r\n',1,1,'2026-01-03 23:41:17.537','2026-01-03 23:41:17.537'),
(2,1,'Nhập xuất cơ bản – Bước khởi đầu','# 📥📤 Nhập Xuất Cơ Bản\r\n\r\nĐây là nhóm bài **dễ nhất**, phù hợp cho người mới.\r\n\r\n## Nội dung thường gặp\r\n- Đọc số nguyên, số thực\r\n- Đọc xâu ký tự\r\n- In kết quả đúng định dạng\r\n\r\n## Ví dụ\r\n```text\r\nInput:\r\n5 7\r\n\r\nOutput:\r\n12\r\n```\r\n\r\n> ⚠️ In **đúng format**, sai 1 dấu cách vẫn bị Wrong Answer.\r\n',1,1,'2026-01-03 23:41:17.537','2026-01-03 23:41:17.537'),
(3,1,'Tư duy giải thuật là gì?','# 🧠 Tư duy giải thuật\r\n\r\nTư duy giải thuật là khả năng:\r\n- Phân tích bài toán\r\n- Chia nhỏ vấn đề\r\n- Chọn cách giải tối ưu\r\n\r\n## Quy trình cơ bản\r\n1. Hiểu đề\r\n2. Xác định input/output\r\n3. Chọn thuật toán\r\n4. Code + test\r\n\r\n> 💬 Code nhanh chưa chắc đã tốt, **code đúng và tối ưu mới quan trọng**.\r\n',1,1,'2026-01-03 23:41:17.537','2026-01-03 23:41:17.537'),
(4,1,'Mảng một chiều – Kiến thức nền tảng','# 📦 Mảng Một Chiều\r\n\r\nMảng là cấu trúc dữ liệu xuất hiện **rất thường xuyên**.\r\n\r\n## Các thao tác cơ bản\r\n- Duyệt mảng\r\n- Tìm max / min\r\n- Đếm phần tử\r\n- Tính tổng\r\n\r\n## Lỗi thường gặp\r\n- Truy cập ngoài phạm vi mảng\r\n- Quên khởi tạo giá trị\r\n',1,1,'2026-01-03 23:41:17.537','2026-01-03 23:41:17.537'),
(5,1,'Xử lý xâu ký tự','# 🔤 Xâu Ký Tự\r\n\r\nXử lý chuỗi là kỹ năng **bắt buộc**.\r\n\r\n## Bài toán phổ biến\r\n- Đếm ký tự\r\n- Chuẩn hóa xâu\r\n- Kiểm tra đối xứng\r\n\r\n```cpp\r\nstring s;\r\ngetline(cin, s);\r\n```\r\n',1,1,'2026-01-03 23:41:17.537','2026-01-03 23:41:17.537'),
(6,1,'Sắp xếp – Thuật toán kinh điển','# 🔀 Thuật Toán Sắp Xếp\r\n\r\n## Thuật toán thường gặp\r\n- Bubble Sort\r\n- Selection Sort\r\n- Quick Sort\r\n- Merge Sort\r\n\r\n| Thuật toán | Độ phức tạp |\r\n|-----------|-------------|\r\n| Bubble    | O(n^2)      |\r\n| Quick     | O(n log n)  |\r\n',1,1,'2026-01-03 23:41:17.537','2026-01-03 23:41:17.537'),
(7,1,'Tìm kiếm trong mảng','# 🔍 Thuật Toán Tìm Kiếm\r\n\r\n## Phổ biến\r\n- Tìm kiếm tuyến tính\r\n- Tìm kiếm nhị phân\r\n\r\n> ⚠️ Tìm kiếm nhị phân yêu cầu mảng đã được sắp xếp.\r\n',1,1,'2026-01-03 23:41:17.537','2026-01-03 23:41:17.537'),
(8,1,'Đệ quy – Con dao hai lưỡi','# 🔁 Đệ Quy\r\n\r\n## Khi nào nên dùng?\r\n- Bài toán chia nhỏ\r\n- Cấu trúc cây\r\n\r\n## Lưu ý\r\n- Tránh đệ quy vô hạn\r\n- Chú ý tràn stack\r\n',1,1,'2026-01-03 23:41:17.537','2026-01-03 23:41:17.537'),
(9,1,'Quy hoạch động nhập môn','# 🧩 Quy Hoạch Động\r\n\r\n## Ý tưởng\r\n- Lưu kết quả bài toán con\r\n- Tránh tính toán lặp\r\n\r\n## Ví dụ\r\n- Fibonacci\r\n- Bài toán cái túi\r\n',1,1,'2026-01-03 23:41:17.537','2026-01-03 23:41:17.537'),
(10,1,'Lời khuyên khi thi lập trình','# 🏁 Kinh Nghiệm Thi Lập Trình\r\n\r\n## Trước khi thi\r\n- Luyện đề cơ bản\r\n- Nắm chắc cú pháp\r\n\r\n## Khi làm bài\r\n- Đọc kỹ đề\r\n- Test kỹ\r\n\r\n> 💪 Bình tĩnh là chìa khóa!\r\n',1,1,'2026-01-03 23:41:17.537','2026-01-03 23:41:17.537'),
(11,2,'Đổi ảnh đại diện','# 🖼️ Hướng dẫn đổi Avatar (Ảnh đại diện)\n\nHệ thống **Kra-tognoek** sử dụng **Gravatar** để hiển thị ảnh đại diện người dùng.\n\n👉 Chỉ cần **1 email**, avatar của bạn sẽ tự động hiển thị trên toàn hệ thống.\n\n---\n\n## 🌐 Gravatar là gì?\n\n**Gravatar (Globally Recognized Avatar)** là dịch vụ ảnh đại diện toàn cầu.\n\n- Mỗi **email** tương ứng với **1 avatar**\n- Nhiều website lập trình, blog, forum sử dụng\n- Bạn **không cần upload ảnh trực tiếp** lên website\n\n---\n\n## 🛠️ Cách đổi Avatar\n\n### Bước 1: Truy cập Gravatar\n🔗 https://gravatar.com\n\n---\n\n### Bước 2: Đăng nhập / Đăng ký\n- Đăng nhập bằng **email bạn dùng để đăng ký tài khoản trên Kra-tognoek**\n- Nếu chưa có tài khoản → tạo mới\n\n⚠️ **Email phải trùng khớp 100%**\n\n---\n\n### Bước 3: Upload ảnh đại diện\n- Chọn **Upload Image**\n- Có thể:\n  - Upload từ máy\n  - Chụp webcam\n  - Chọn ảnh từ URL\n\n---\n\n### Bước 4: Gán ảnh cho email\n- Chọn email bạn đang dùng\n- Lưu lại\n\n⏳ Avatar có thể mất **1–5 phút** để cập nhật\n\n---\n\n## 🔄 Kiểm tra Avatar trên hệ thống\n\n- Đăng xuất → đăng nhập lại\n- Hoặc **F5 / Ctrl + Shift + R** để reload cache\n- Avatar sẽ tự động hiển thị\n\n---\n\n## 🖼️ Nếu chưa có avatar?\n\nHệ thống sẽ hiển thị **avatar mặc định** (identicon / hình ngẫu nhiên).\n\n---\n\n## ❓ Câu hỏi thường gặp\n\n### ❔ Tôi đổi ảnh nhưng chưa thấy cập nhật?\n✔️ Chờ vài phút  \n✔️ Kiểm tra đúng email  \n✔️ Xóa cache trình duyệt\n\n---\n\n### ❔ Tôi không muốn dùng Gravatar?\n➡️ Hệ thống hiện tại **chỉ hỗ trợ Gravatar**\n\n---\n\n## 📌 Lưu ý quan trọng\n\n- Email **không hiển thị công khai**\n- Hệ thống chỉ sử dụng **hash MD5** để lấy ảnh\n- An toàn & phổ biến trong cộng đồng lập trình\n\n---\n\n## 💡 Mẹo\nBạn có thể dùng **1 avatar cho nhiều website dev khác nhau** chỉ với 1 email 🚀\n',3,1,'2026-01-03 20:02:05.880','2026-01-03 20:09:05.623');
INSERT INTO `BaiNop` VALUES
(1,1,1,2,NULL,'http://127.0.0.1:3001/data/code/admin_1767458980268.cpp','#include<bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    int a, b;\n    cin >> a >> b;\n    cout << a * b;\n}','[0]',30,3000,'2026-01-03 16:49:40'),
(2,1,1,2,NULL,'http://127.0.0.1:3001/data/code/admin_1767459016661.cpp','#include <iostream>\n#include <vector>\n#include <algorithm>\n\nusing namespace std;\n\nvoid solve() {\n    int n;\n    long long k;\n    if (!(cin >> n >> k)) return;\n\n    vector<int> a(n);\n    for (int i = 0; i < n; ++i) {\n        cin >> a[i];\n    }\n\n    sort(a.begin(), a.end());\n    a.erase(unique(a.begin(), a.end()), a.end());\n\n    int m = a.size();\n    if (m == 0) {\n        cout << -1 << endl;\n        return;\n    }\n\n    int max_val = a.back();\n    vector<int> valid_candidates;\n\n    for (int x : a) {\n        long long last_multiple = (k / x) * x;\n        if (last_multiple > max_val) {\n            continue; \n        }\n\n        bool is_valid = true;\n        for (long long v = 2LL * x; v <= max_val; v += x) {\n            if (!binary_search(a.begin(), a.end(), (int)v)) {\n                is_valid = false;\n                break;\n            }\n        }\n\n        if (is_valid) {\n            valid_candidates.push_back(x);\n        }\n    }\n\n    vector<int> B;\n    vector<bool> removed(valid_candidates.size(), false);\n\n    for (int i = 0; i < valid_candidates.size(); ++i) {\n        if (removed[i]) continue;\n        \n        int val = valid_candidates[i];\n        B.push_back(val);\n\n        for (long long v = 2LL * val; v <= max_val; v += val) {\n            auto it = lower_bound(valid_candidates.begin() + i + 1, valid_candidates.end(), (int)v);\n            if (it != valid_candidates.end() && *it == v) {\n                removed[it - valid_candidates.begin()] = true;\n            }\n        }\n    }\n\n    vector<bool> is_covered(m, false);\n    int covered_count = 0;\n\n    for (int x : B) {\n        for (long long v = x; v <= max_val; v += x) {\n            auto it = lower_bound(a.begin(), a.end(), (int)v);\n            if (it != a.end() && *it == v) {\n                int idx = it - a.begin();\n                if (!is_covered[idx]) {\n                    is_covered[idx] = true;\n                    covered_count++;\n                }\n            }\n        }\n    }\n\n    if (covered_count == m) {\n        cout << B.size() << endl;\n        for (int x : B) {\n            cout << x << \" \";\n        }\n        cout << endl;\n    } else {\n        cout << -1 << endl;\n    }\n}\n\nint main() {\n    ios_base::sync_with_stdio(false);\n    cin.tie(NULL);\n    \n    int t;\n    if (cin >> t) {\n        while (t--) {\n            solve();\n        }\n    }\n    return 0;\n}','[1]',100,3452,'2026-01-03 16:50:16'),
(3,1,2,2,NULL,'http://127.0.0.1:3001/data/code/admin_1767459169780.cpp','#include <iostream>\n#include <cmath>\n#include <vector>\n\nusing namespace std;\n\nbool isPrime(long long n) {\n    if (n < 2) return false;\n    if (n == 2 || n == 3) return true;\n    if (n % 2 == 0 || n % 3 == 0) return false;\n    \n    for (long long i = 5; i * i <= n; i += 6) {\n        if (n % i == 0 || n % (i + 2) == 0) {\n            return false;\n        }\n    }\n    return true;\n}\n\nint main() {\n    ios_base::sync_with_stdio(false);\n    cin.tie(NULL);\n\n    int n;\n    if (!(cin >> n)) return 0;\n\n    int count = 0;\n    for (int i = 0; i < n; i++) {\n        long long a;\n        cin >> a;\n        if (isPrime(a)) {\n            count++;\n        }\n    }\n\n    cout << count << endl;\n\n    return 0;\n}','[1,1,1]',NULL,0,'2026-01-03 16:52:49'),
(4,1,2,2,NULL,'http://127.0.0.1:3001/data/code/admin_1767459401853.cpp','#include <iostream>\n#include <cmath>\n#include <vector>\n\nusing namespace std;\n\nbool isPrime(long long n) {\n    if (n < 2) return false;\n    if (n == 2 || n == 3) return true;\n    if (n % 2 == 0 || n % 3 == 0) return false;\n    \n    for (long long i = 5; i * i <= n; i += 6) {\n        if (n % i == 0 || n % (i + 2) == 0) {\n            return false;\n        }\n    }\n    return true;\n}\n\nint main() {\n    ios_base::sync_with_stdio(false);\n    cin.tie(NULL);\n\n    int n;\n    if (!(cin >> n)) return 0;\n\n    int count = 0;\n    for (int i = 0; i < n; i++) {\n        long long a;\n        cin >> a;\n        if (isPrime(a)) {\n            count++;\n        }\n    }\n\n    cout << count << endl;\n\n    return 0;\n}','[1,1,1]',0,0,'2026-01-03 16:56:41'),
(5,1,2,2,NULL,'http://127.0.0.1:3001/data/code/admin_1767459991696.cpp','#include <iostream>\n#include <cmath>\n#include <vector>\n\nusing namespace std;\n\nbool isPrime(long long n) {\n    if (n < 2) return false;\n    if (n == 2 || n == 3) return true;\n    if (n % 2 == 0 || n % 3 == 0) return false;\n    \n    for (long long i = 5; i * i <= n; i += 6) {\n        if (n % i == 0 || n % (i + 2) == 0) {\n            return false;\n        }\n    }\n    return true;\n}\n\nint main() {\n    ios_base::sync_with_stdio(false);\n    cin.tie(NULL);\n\n    int n;\n    if (!(cin >> n)) return 0;\n\n    int count = 0;\n    for (int i = 0; i < n; i++) {\n        long long a;\n        cin >> a;\n        if (isPrime(a)) {\n            count++;\n        }\n    }\n\n    cout << count << endl;\n\n    return 0;\n}','[1,1,1]',0,0,'2026-01-03 17:06:31'),
