(17,1,2,2,NULL,'http://127.0.0.1:3001/data/code/admin_1767461115030.cpp','#include <iostream>\n#include <cmath>\n#include <vector>\n\nusing namespace std;\n\nbool isPrime(long long n) {\n    if (n < 2) return false;\n    if (n == 2 || n == 3) return true;\n    if (n % 2 == 0 || n % 3 == 0) return false;\n    \n    for (long long i = 5; i * i <= n; i += 6) {\n        if (n % i == 0 || n % (i + 2) == 0) {\n            return false;\n        }\n    }\n    return true;\n}\n\nint main() {\n    ios_base::sync_with_stdio(false);\n    cin.tie(NULL);\n\n    int n;\n    if (!(cin >> n)) return 0;\n\n    int count = 0;\n    for (int i = 0; i < n; i++) {\n        long long a;\n        cin >> a;\n        if (isPrime(a)) {\n            count++;\n        }\n    }\n\n    cout << count << endl;\n\n    return 0;\n}','[-1]',0,0,'2026-01-03 17:25:15'),
