(46,1,2,1,NULL,'http://127.0.0.1:3001/data/code/admin_1767464314334.cpp','#include <iostream>\n#include <cmath>\n#include <vector>\n\nusing namespace std;\n\nbool isPrime(long long n) {\n    if (n < 2) return false;\n    if (n == 2 || n == 3) return true;\n    if (n % 2 == 0 || n % 3 == 0) return false;\n    \n    for (long long i = 5; i * i <= n; i += 6) {\n        if (n % i == 0 || n % (i + 2) == 0) {\n            return false;\n        }\n    }\n    return true;\n}\n\nint main() {\n    ios_base::sync_with_stdio(false);\n    cin.tie(NULL);\n\n    int n;\n    if (!(cin >> n)) return 0;\n\n    int count = 0;\n    for (int i = 0; i < n; i++) {\n        long long a;\n        cin >> a;\n        if (isPrime(a)) {\n            count++;\n        }\n    }\n\n    cout << count << endl;\n\n    return 0;\n}','[0,0,0]',4,3432,'2026-01-03 18:18:34'),
(47,1,19,1,NULL,'http://127.0.0.1:3001/data/code/admin_1767469040495.cpp','#include <iostream>\n#include <string>\n#include <algorithm>\n\nusing namespace std;\n\nint main() {\n    ios_base::sync_with_stdio(false);\n    cin.tie(NULL);\n\n    unsigned long long n;\n    if (!(cin >> n)) return 0;\n\n    if (n == 0) {\n        cout << 0 << endl;\n        return 0;\n    }\n\n    string binary = \"\";\n    \n    while (n > 0) {\n        if (n % 2 == 0) {\n            binary += \'0\';\n        } else {\n            binary += \'1\';\n        }\n        n /= 2;\n    }\n\n    reverse(binary.begin(), binary.end());\n\n    cout << binary << endl;\n\n    return 0;\n}','[0,0,0]',4,3568,'2026-01-03 19:37:20'),
(48,1,26,2,NULL,'http://127.0.0.1:3001/data/code/admin_1767469381772.c','#include <stdio.h>\n\nint main() {\n    int a, b;\n    scanf(\"%d %d\", &a, &b);\n    printf(\"%d\", a + b);\n    return 0;\n}\n','[0,0,0]',3,1568,'2026-01-03 19:43:01'),
(49,1,28,1,NULL,'http://127.0.0.1:3001/data/code/admin_1767469838742.cpp','#include <iostream>\n\nusing namespace std;\n\nint main() {\n    ios_base::sync_with_stdio(false);\n    cin.tie(NULL);\n\n    int n;\n    long long k;\n    if (!(cin >> n >> k)) return 0;\n\n    long long tong = 0; \n    long long temp;\n\n    for (int i = 0; i < n; i++) {\n        cin >> temp;\n        if (temp > k) {\n            tong += temp;\n        }\n    }\n\n    cout << tong << endl;\n\n    return 0;\n}','[0,0,0]',5,3612,'2026-01-03 19:50:38'),
(50,2,22,1,NULL,'http://127.0.0.1:3001/data/code/thong_1767471030311.cpp','#include <iostream>\n#include <cmath>\n\nusing namespace std;\n\nbool isPrime(long long n) {\n    if (n < 2) return false;\n\n    for (int i = 2; i <= sqrt(n); i++) {\n        if (n % i == 0) {\n            return false;\n        }\n    }\n    \n    return true;\n}\n\nint main() {\n    long long n;\n    if (cin >> n) {\n        if (isPrime(n)) {\n            cout << \"YES\" << endl;\n        } else {\n            cout << \"NO\" << endl;\n        }\n    }\n    return 0;\n}','[0,0,0]',3,3588,'2026-01-03 20:10:30'),
