INSERT INTO `DeBai` VALUES
(1,2,'TÍCH HAI SỐ','## 📝 Mô tả bài toán\nCho hai số nguyên **A** và **B**.  \nHãy tính **tích của hai số A và B**.\n\n---\n## 📥 Dữ liệu vào\n\n- Một dòng duy nhất chứa hai số nguyên **A** và **B**\n- Hai số cách nhau bởi một dấu cách\n---\n## 📤 Dữ liệu ra\n\n- In ra **tích của A và B**\n---\n## 🔒 Ràng buộc\n\n- −10⁹ ≤ A, B ≤ 10⁹\n---\n## 🧪 Ví dụ\n\n### Ví dụ 1\n\n**Input**\n```\n3 5\n```\n**Output**\n```\n15\n```\n---\n## 💡 Gợi ý\n- Chỉ cần đọc hai số và in ra tích\n- Chú ý kiểu dữ liệu đủ lớn để tránh tràn số','1',1000,262144,1,'2026-01-03 16:48:12',1),
(2,1,'ĐẾM SỐ NGUYÊN TỐ','# ĐẾM SỐ LƯỢNG SỐ NGUYÊN TỐ TRONG MẢNG\n## 📝 Đề bài\nCho một mảng gồm **n** số nguyên dương $a_1, a_2, ..., a_n$.  \nHãy đếm xem trong mảng có bao nhiêu số là **số nguyên tố**.\n\nMột số được gọi là **số nguyên tố** nếu:\n- Lớn hơn 1\n- Chỉ có đúng **hai ước số dương** là 1 và chính nó\n---\n\n## 📥 Dữ liệu vào\n- Dòng đầu tiên chứa số nguyên dương **n** (số lượng phần tử của mảng)\n- Dòng thứ hai chứa **n** số nguyên $a_1, a_2, ..., a_n$, mỗi số cách nhau một khoảng trắng\n---\n## 📤 Dữ liệu ra\n- Một số nguyên duy nhất là số lượng số nguyên tố có trong mảng\n---\n## 📌 Ví dụ\n**Input**\n```\n5\n2 3 4 5 10\n```\n**Output**\n```\n3\n```','4',1000,262144,1,'2026-01-03 16:52:22',1),
(3,1,'BẬC THANG DANH VỌNG','## 📖 Leo núi\nỞ vương quốc \"Số Học\", có một ngọn núi cao tên là **Olympus**. Để leo lên đỉnh núi, các nhà thám hiểm phải bước qua những bậc thang đá cổ xưa. Tuy nhiên, ngọn núi này có một lời nguyền: Chỉ những con số mang hình dáng của một \"chiếc cầu thang đi lên\" mới có thể mở cửa kho báu trên đỉnh núi.\n\nMột con số được gọi là **Số bậc thang** nếu các chữ số của nó (tính từ trái sang phải) luôn giữ vững phong độ: chữ số đứng sau phải **lớn hơn** chữ số đứng trước. Ví dụ, số `125` là số bậc thang, nhưng số `132` thì không vì từ `3` lại tụt xuống `2`.\n\nHãy giúp các nhà thám hiểm kiểm tra xem mật mã họ tìm được có phải là chiếc chìa khóa để mở cửa kho báu không nhé!\n\n---\n## 📝 Đề bài\n\nCho một số nguyên dương **N**.  \nHãy kiểm tra xem **N** có phải là số bậc thang (các chữ số tăng dần nghiêm ngặt từ trái sang phải) hay không.\n\n---\n## 📥 Dữ liệu vào\n- Một dòng duy nhất chứa số nguyên dương **N** ($10 \\le N \\le 10^{18}$).\n---\n## 📤 Dữ liệu ra\n\n- In ra `YES` nếu **N** là số bậc thang.\n- In ra `NO` nếu **N** không phải là số bậc thang.\n---\n## 📌 Ví dụ\n\n**Input**\n```\n12379\n```\n**Output**\n```\nYES\n```','5',1000,262144,1,'2026-01-03 18:38:28',1),
(4,1,'TÌM BỘI SỐ CHUNG NHỎ NHẤT','## 📝 Đề bài\nCho hai số nguyên dương **a** và **b**.  \nHãy tìm **Bội số chung nhỏ nhất (BCNN)** của hai số đó.\n\nBội số chung nhỏ nhất của hai số nguyên là số nguyên dương nhỏ nhất chia hết cho cả hai số đó.\n\n---\n## 📥 Dữ liệu vào\n- Một dòng duy nhất chứa hai số nguyên dương **a** và **b**, cách nhau một khoảng trắng.\n---\n## 📤 Dữ liệu ra\n- Một số nguyên duy nhất là bội số chung nhỏ nhất của **a** và **b**.\n---\n## 📌 Ví dụ\n**Input**\n```\n4 6\n```\n**Input**\n```\n12\n```','3',1000,262144,1,'2026-01-03 18:39:07',1),
(5,1,'KIỂM TRA SỐ CHẴN LẺ','## 📝 Đề bài\nCho một số nguyên N. Hãy xác định N là số chẵn hay số lẻ.\n\n## 📥 Dữ liệu vào\n- Một số nguyên N\n## 📤 Dữ liệu ra\n- EVEN nếu N chẵn\n- ODD nếu N lẻ\n## 📌 Ví dụ\nInput:\n```\n7\n```\nOutput:\n```\nODD\n```','1',1000,262144,1,'2026-01-03 18:39:36',1),
(6,2,' PHẦN DƯ','## 📝 Đề bài\nCho hai số nguyên A và B. Hãy tính phép chia dư của hai số đó.\n## 📥 Dữ liệu vào\n- Một dòng chứa hai số nguyên A, B\n## 📤 Dữ liệu ra\n- In ra giá trị A % B\n## 📌 Ví dụ\nInput:\n```\n5 3\n```\nOutput:\n```\n2\n```','2',500,262144,1,'2026-01-03 18:40:14',1),
(7,1,'CHUẨN HÓA XÂU','## 📝 Đề bài\nCho một xâu ký tự **S** gồm các chữ cái và khoảng trắng. Hãy **chuẩn hóa xâu** theo các yêu cầu sau:\n\n* Loại bỏ các khoảng trắng thừa ở đầu và cuối xâu\n* Giữa hai từ chỉ còn **một khoảng trắng**\n* Ký tự đầu tiên của mỗi từ được viết **hoa**, các ký tự còn lại viết **thường**\n\n---\n## 📥 Dữ liệu vào\n* Một dòng duy nhất chứa xâu **S**\n---\n## 📤 Dữ liệu ra\n* In ra xâu **sau khi đã được chuẩn hóa**\n---\n## 📌 Ví dụ\n### Input\n```\n   nGuYEN   vAn    a   \n```\n### Output\n```\nNguyen Van A\n```\n','8',1000,262144,1,'2026-01-03 18:41:15',1),
(8,1,'CUỘC HẸN CỦA HAI NGƯỜI THỢ BÁNH','## 📖 An và Bình\nTrong một thị trấn nhỏ, có hai người thợ làm bánh nổi tiếng là **An** và **Bình**.\n- Anh **An** cứ **a** ngày lại ra chợ thị trấn để nhập bột mì một lần.\n- Anh **Bình** cứ **b** ngày lại ra chợ thị trấn để nhập men nở một lần.\n\nHôm nay, cả hai anh vô tình gặp nhau tại chợ. Họ rất vui mừng và tự hỏi: \"Không biết sau ít nhất bao nhiêu ngày nữa thì hai chúng ta mới lại cùng nhau đi chợ vào đúng một ngày nhỉ?\".\n\nHãy giúp hai anh thợ bánh tìm ra số ngày ngắn nhất để họ gặp lại nhau tại chợ!\n\n---\n## 📝 Đề bài\nCho hai số nguyên dương **a** và **b** tương ứng là chu kỳ đi chợ của anh An và anh Bình.  \nHãy tìm số nguyên dương nhỏ nhất chia hết cho cả **a** và **b** (Bội số chung nhỏ nhất).\n\n---\n## 📥 Dữ liệu vào\n- Một dòng duy nhất chứa hai số nguyên dương **a** và **b** ($1 \\le a, b \\le 10^9$).\n---\n## 📤 Dữ liệu ra\n- Một số nguyên duy nhất là số ngày ít nhất để hai anh gặp lại nhau.\n---\n## 📌 Ví dụ\n**Input**\n```\n4 6\n```\n**Output*\n```\n12\n```','7',1000,262144,1,'2026-01-03 18:42:31',1),
(9,1,' CUỘC DI CƯ CỦA BẦY VOI','## 📖 Cân voi\nMùa khô hạn đã đến, bầy voi rừng phải di cư để tìm nguồn nước mới. Trên đường đi, bầy voi phải vượt qua một con sông sâu. Trong bầy có **n** chú voi với các mức cân nặng khác nhau.\n\nĐể đảm bảo an toàn, con voi đầu đàn muốn tìm ra chú voi có **cân nặng nhỏ nhất** để ưu tiên đi ở giữa đàn, nơi dòng nước chảy yếu nhất và được các con voi lớn hơn che chắn.\n\nBạn hãy giúp voi đầu đàn tìm ra cân nặng của chú voi \"em út\" này nhé!\n\n---\n## 📝 Đề bài\nCho một mảng gồm **n** số nguyên dương $a_1, a_2, ..., a_n$ lần lượt là cân nặng của các chú voi.\nHãy tìm giá trị **nhỏ nhất** (Minimum) trong mảng đó.\n\n---\n## 📥 Dữ liệu vào\n- Dòng đầu tiên chứa số nguyên dương **n** (số lượng voi trong đàn).\n- Dòng thứ hai chứa **n** số nguyên dương $a_1, a_2, ..., a_n$ ($1 \\le a_i \\le 10^9$), mỗi số cách nhau một khoảng trắng.\n---\n## 📤 Dữ liệu ra\n- Một số nguyên duy nhất là cân nặng của chú voi nhỏ nhất tìm được.\n---\n## 📌 Ví dụ\n**Input**\n```\n5\n1500 2800 1200 3500 2100\n```\n*Output*\n```\n1200\n```','5',1000,262144,1,'2026-01-03 18:43:16',1),
(10,1,'ĐỘI QUÂN CỦA NHÀ VUA','## 📖 Hãy cứu vương quốc\nỞ một vương quốc nọ, Đức vua chuẩn bị tổ chức một buổi lễ duyệt binh hoành tráng. Có **n** chiến binh tham gia vào đội hình danh dự. Tuy nhiên, các chiến binh lại đứng lộn xộn, người cao người thấp không đồng đều, làm cho đội hình trông rất thiếu thẩm mỹ.\n\nĐức vua ra lệnh cho vị tướng chỉ huy phải sắp xếp lại các chiến binh sao cho người thấp nhất đứng đầu hàng, người cao nhất đứng cuối hàng. Nói cách khác, chiều cao của các chiến binh phải **tăng dần** từ trái qua phải để khi nhìn vào, đội hình sẽ trông như một mũi tên vươn cao.\n\nHãy giúp vị tướng chỉ huy sắp xếp lại chiều cao của các chiến binh này nhé!\n\n---\n## 📝 Đề bài\n\nCho một mảng gồm **n** số nguyên dương $a_1, a_2, ..., a_n$ đại diện cho chiều cao của từng chiến binh.\nHãy sắp xếp mảng này theo thứ tự **tăng dần**.\n\n---\n## 📥 Dữ liệu vào\n- Dòng đầu tiên chứa số nguyên dương **n** (số lượng chiến binh).\n- Dòng thứ hai chứa **n** số nguyên dương $a_1, a_2, ..., a_n$ ($1 \\le a_i \\le 10^9$), mỗi số cách nhau một khoảng trắng.\n---\n## 📤 Dữ liệu ra\n- Một dòng duy nhất chứa dãy số đã được sắp xếp tăng dần, mỗi số cách nhau một khoảng trắng.\n---\n## 📌 Ví dụ\n**Input**\n```\n5\n170 165 180 155 175\n```\n**Output**\n```\n155 165 170 175 180\n```','5',1000,262144,1,'2026-01-03 18:44:41',1),
(11,1,'ĐỘI HÌNH DUYỆT BINH HOÀNH TRÁNG','## 📖 Tình người\nỞ một vương quốc nọ, Đức vua chuẩn bị tổ chức một buổi lễ duyệt binh vô cùng lớn để chào đón năm mới. Có **n** chiến binh tinh nhuệ được tuyển chọn vào đội hình danh dự. Tuy nhiên, lúc tập trung, các chiến binh lại đứng lộn xộn: người cao, người thấp xen kẽ nhau làm cho hàng ngũ trông không được đẹp mắt.\n\nVị tướng chỉ huy muốn sắp xếp lại các chiến binh sao cho người thấp nhất đứng ở đầu hàng và chiều cao **tăng dần** về phía cuối hàng. Khi đó, đội hình nhìn từ xa sẽ trông như một mũi tên vươn cao đầy mạnh mẽ.\n\nHãy giúp vị tướng sắp xếp lại danh sách chiều cao của các chiến binh để buổi lễ diễn ra tốt đẹp nhé!\n\n---\n## 📝 Đề bài\n\nCho một mảng gồm **n** số nguyên dương $a_1, a_2, ..., a_n$ lần lượt là chiều cao của các chiến binh.  \nHãy sắp xếp dãy số này theo thứ tự **tăng dần**.\n\n---\n## 📥 Dữ liệu vào\n- Dòng đầu tiên chứa số nguyên dương **n** $\\le  10^6$ (số lượng chiến binh).\n- Dòng thứ hai chứa **n** số nguyên dương $a_i$ ($1 \\le a_i \\le 10^9$), mỗi số cách nhau một khoảng trắng.\n---\n## 📤 Dữ liệu ra\n- Một dòng duy nhất chứa dãy chiều cao đã được sắp xếp tăng dần, mỗi số cách nhau một khoảng trắng.\n---\n## 📌 Ví dụ\n**Input**\n```\n5\n170 165 180 155 175\n```\n**Output**\n```\n155 165 170 175 180\n```','6',1000,262144,1,'2026-01-03 18:46:46',1),
(12,1,'TÌM SỐ FIBONACCI THỨ N','## 📝 Đề bài\nCho một số nguyên không âm **n**. Hãy tính và in ra **số Fibonacci thứ n**.\n\nDãy Fibonacci được định nghĩa như sau:\n\n* F(0) = 0\n* F(1) = 1\n* F(n) = F(n - 1) + F(n - 2) với n ≥ 2\n\n---\n## 📥 Dữ liệu vào\n* Một số nguyên **n**\n* Điều kiện: `0 ≤ n < 100`\n---\n## 📤 Dữ liệu ra\n* In ra **số Fibonacci thứ n**\n---\n## 📌 Ví dụ\n### Input\n```\n7\n```\n### Output\n```\n13\n```','6',1000,262144,1,'2026-01-03 19:24:32',1),
(13,1,'IN CÁC SỐ FIBONACCI BÉ HƠN K','## 📝 Đề bài\nCho một số nguyên dương **k**.  \nHãy liệt kê tất cả các số thuộc **dãy Fibonacci** có giá trị nhỏ hơn hoặc bằng **k**.\n\nQuy ước dãy Fibonacci bắt đầu bằng: $0, 1, 1, 2, 3, 5, 8, 13, ...$\n\n---\n## 📥 Dữ liệu vào\n- Một dòng duy nhất chứa số nguyên dương **k**\n---\n## 📤 Dữ liệu ra\n- Một dòng duy nhất chứa các số Fibonacci nhỏ hơn hoặc bằng **k**, mỗi số cách nhau một khoảng trắng\n---\n## 📌 Ví dụ\n**Input**\n```\n20\n```\n**Output**\n```\n0 1 1 2 3 5 8 13\n```','5',1000,262144,1,'2026-01-03 19:27:04',1),
(14,1,'HÀNG RÀO BẢO VỆ','## 📖 Câu chuyện\nBác nông dân **John** vừa mua được **n** thanh gỗ có độ dài khác nhau. Bác muốn chọn ra **3 thanh gỗ** để dựng thành một chiếc khung hình tam giác nhằm bảo vệ vườn hoa nhỏ của mình.\n\nBác John muốn chiếc hàng rào này phải có **chu vi lớn nhất** có thể để bao quanh được nhiều diện tích nhất. Tuy nhiên, bác cũng biết rằng không phải cứ chọn đại 3 thanh gỗ là có thể ghép thành tam giác (tổng độ dài 2 cạnh bất kỳ phải luôn lớn hơn cạnh còn lại).\n\nHãy giúp bác John tìm ra chu vi lớn nhất của hàng rào mà bác có thể dựng được!\n\n---\n\n## 📝 Đề bài\nCho một mảng gồm **n** số nguyên dương $a_1, a_2, ..., a_n$ là độ dài của các thanh gỗ.  \nHãy tìm 3 thanh gỗ có thể tạo thành một tam giác sao cho **tổng độ dài của chúng là lớn nhất**.\n\n---\n\n## 📥 Dữ liệu vào\n- Dòng đầu tiên chứa số nguyên dương **n** ($3 \\le n \\le 10^5$).\n- Dòng thứ hai chứa **n** số nguyên dương $a_i$ ($1 \\le a_i \\le 10^9$), mỗi số cách nhau một khoảng trắng.\n---\n## 📤 Dữ liệu ra\n- Một số nguyên duy nhất là chu vi lớn nhất tìm được. Nếu không thể tạo thành bất kỳ tam giác nào, in ra `-1`.\n---\n## 📌 Ví dụ\n**Input**\n```\n5\n2 1 2 10 1\n```\n**Output**\n```\n5\n```','9',1000,262144,1,'2026-01-03 19:28:00',1),
(15,2,'HIỆU HAI SỐ','## 📝 Đề bài\nCho hai số nguyên A và B. Hãy tính hiệu của hai số đó.\n## 📥 Dữ liệu vào\n- Một dòng chứa hai số nguyên A, B\n## 📤 Dữ liệu ra\n- In ra hiệu A - B\n## 📌 Ví dụ\nInput:\n```\n3 5\n```\nOutput:\n```\n-2\n```','2',1000,262144,1,'2026-01-03 19:28:30',1),
(16,1,'KẺ TRỘM BÍ ẨN TRONG NGÔI LÀNG','## 📖 Kẻ trộm đồ\nNgôi làng \"Số Học\" vốn đang yên bình thì bỗng nhiên xảy ra nhiều vụ mất trộm vặt. Sau khi điều tra, bác trưởng làng thu thập được một danh sách các số hiệu **ID** của những người xuất hiện gần hiện trường các vụ án.\n\nDân làng nghi ngờ rằng: Kẻ trộm chính là người **xuất hiện nhiều lần nhất** trong danh sách thu thập được, vì hắn ta lảng vảng quanh các ngôi nhà bị mất trộm nhiều hơn bất kỳ ai khác.\n\nBác trưởng làng đang rất lúng túng với tờ danh sách dài dằng dặc. Bạn hãy giúp bác tìm ra số hiệu ID của tên trộm bí ẩn này nhé!\n\n---\n## 📝 Đề bài\nCho một mảng gồm **n** số nguyên dương $a_1, a_2, ..., a_n$ là các số hiệu ID.\nHãy tìm số hiệu xuất hiện với **tần suất nhiều nhất** trong mảng.\n\n*Lưu ý: Nếu có nhiều số có cùng số lần xuất hiện lớn nhất, hãy in ra số có giá trị nhỏ nhất.*\n---\n## 📥 Dữ liệu vào\n\n- Dòng đầu tiên chứa số nguyên dương **n** (số lượng ID trong danh sách).\n- Dòng thứ hai chứa **n** số nguyên dương $a_1, a_2, ..., a_n$ ($1 \\le a_i \\le 10^6$), mỗi số cách nhau một khoảng trắng.\n\n---\n## 📤 Dữ liệu ra\n- Một số nguyên duy nhất là số hiệu ID xuất hiện nhiều nhất.\n---\n## 📌 Ví dụ\n**Input**\n```\n7\n10 20 10 30 20 10 40\n```\n**Output**\n```\n10\n```','7',1000,262144,1,'2026-01-03 19:29:24',1),
(17,1,'NHÀ THÁM HIỂM VÀ NHỮNG VIÊN KIM CƯƠNG','## 📖 Kho báu\nNhà thám hiểm **Jones** vừa tìm thấy một hang động chứa đầy kim cương. Sau khi đo đạc kích thước của **n** viên kim cương tìm được, ông muốn chọn ra một viên để tặng cho viện bảo tàng quốc gia.\n\nTuy nhiên, viên kim cương lớn nhất đã được Jones quyết định giữ lại để nghiên cứu bí mật. Vì vậy, ông muốn tìm viên kim cương có **kích thước lớn thứ hai** để đem đi tặng.\n\nBạn hãy giúp Jones xác định kích thước của viên kim cương đặc biệt này nhé!\n\n---\n## 📝 Đề bài\nCho một mảng gồm **n** số nguyên dương $a_1, a_2, ..., a_n$ là kích thước của các viên kim cương.\nHãy tìm giá trị **lớn thứ nhì** trong mảng đó.\n\n*Lưu ý: Nếu mảng có nhiều giá trị bằng nhau và là lớn nhất, giá trị lớn thứ nhì phải là giá trị nhỏ hơn giá trị lớn nhất đó.*\n\n---\n## 📥 Dữ liệu vào\n- Dòng đầu tiên chứa số nguyên dương **n** (số lượng viên kim cương).\n- Dòng thứ hai chứa **n** số nguyên dương $a_i$ ($1 \\le a_i \\le 10^9$), mỗi số cách nhau một khoảng trắng.\n---\n## 📤 Dữ liệu ra\n- Một số nguyên duy nhất là giá trị lớn thứ nhì. Nếu không tồn tại giá trị lớn thứ nhì (ví dụ tất cả các số bằng nhau), in ra `-1`.\n---\n## 📌 Ví dụ\n**Input**\n```\n5\n10 20 15 20 18\n```\n**Output**\n```\n18\n```','6',1000,262144,1,'2026-01-03 19:30:04',1),
(18,1,'MẬT MÃ CỦA ĐẠI ĐỘI TRƯỞNG','## 📖 Mật mã\nTrong một cuộc hành quân bí mật, Đại đội trưởng cần gửi một dãy mật mã gồm **n** con số về căn cứ. Tuy nhiên, để tránh bị kẻ địch giả mạo, quân đội quy ước rằng: Một mật mã hợp lệ phải là một **mật mã đối xứng**.\n\nTức là nếu ta đọc dãy mật mã từ trái sang phải hay từ phải sang trái, dãy số đều phải hoàn toàn giống hệt nhau. Điều này giúp người nhận tin chắc chắn rằng thông tin không bị mất mát hay bị đảo lộn trong quá trình truyền đi.\n\nĐại đội trưởng vừa nhận được một dãy số, bạn hãy giúp ông ấy kiểm tra xem đó có phải là mật mã hợp lệ hay không!\n\n---\n## 📝 Đề bài\nCho một dãy gồm **n** số nguyên $a_1, a_2, ..., a_n$.  \nHãy kiểm tra xem dãy số này có phải là **dãy đối xứng** hay không.\n\n---\n## 📥 Dữ liệu vào\n- Dòng đầu tiên chứa số nguyên dương **n** (số lượng chữ số trong mật mã).\n- Dòng thứ hai chứa **n** số nguyên $a_i$ ($0 \\le a_i \\le 10^9$), mỗi số cách nhau một khoảng trắng.\n---\n## 📤 Dữ liệu ra\n- In ra `YES` nếu dãy số đối xứng.\n- In ra `NO` nếu dãy số không đối xứng.\n---\n## 📌 Ví dụ\n**Input**\n```\n5\n1 2 3 2 1\n```\n**Output**\n```\nYES\n```','6',1000,262144,1,'2026-01-03 19:30:43',1),
(19,1,'MẬT MÃ TRONG HANG ĐÁ','## 📖 Thám hiểm\nTrong một chuyến thám hiểm rừng sâu, **Rô-bốt Alpha** vô tình bị lạc vào một hang đá cổ. Cửa hang đã đóng sập lại và chỉ hiện lên một bảng điều khiển yêu cầu nhập mật mã bằng các ký hiệu `0` và `1`. \n\nTrên vách đá có khắc một số nguyên dương **N** hệ thập phân. Alpha nhận ra rằng để thoát ra ngoài, cậu phải chuyển đổi số **N** này sang **hệ nhị phân** (hệ cơ số 2) và nhập vào máy tính.\n\nBạn hãy giúp Alpha tính toán thật nhanh mật mã nhị phân này để cậu ấy kịp thoát ra trước khi hang đá bị ngập nước nhé!\n\n---\n## 📝 Đề bài\nCho một số nguyên dương **N**.  \nHãy chuyển đổi số **N** từ hệ thập phân sang hệ nhị phân.\n\n---\n## 📥 Dữ liệu vào\n- Một dòng duy nhất chứa số nguyên dương **N** ($1 \\le N \\le 10^{18}$).\n---\n## 📤 Dữ liệu ra\n- Một dãy các ký số `0` và `1` đại diện cho giá trị của **N** ở hệ nhị phân.\n---\n## 📌 Ví dụ\n**Input**\n```\n13\n```\n**Output**\n```\n1101\n```','8',1000,262144,1,'2026-01-03 19:31:16',1),
(20,1,'TÌM SỐ LỚN NHẤT TRONG MẢNG','## 📝 Đề bài\nCho một mảng gồm **n số nguyên**. Hãy tìm và in ra **giá trị lớn nhất** trong mảng đó.\n\n---\n## 📥 Dữ liệu vào\n* Dòng 1: Số nguyên **n** (`1 ≤ n ≤ 10^5`)\n* Dòng 2: **n số nguyên** `a1, a2, ..., an`\n---\n## 📤 Dữ liệu ra\n* In ra **số lớn nhất** trong mảng\n---\n## 📌 Ví dụ\n### Input\n```\n5\n1 7 3 9 2\n```\n### Output\n```\n9\n```','4',1000,262144,1,'2026-01-03 19:31:47',1),
(21,1,'MÓN QUÀ CỦA NHÀ VUA','## 📖 Nhận quà\nĐể chúc mừng ngày hội mùa của vương quốc, Nhà Vua quyết định tặng vàng cho các thần dân. Tuy nhiên, thay vì tặng một số tiền cố định, Nhà Vua đã tạo ra một trò chơi thú vị. Mỗi người dân sẽ được bốc thăm một con số may mắn **N**.\n\nSố lượng thỏi vàng mà người đó nhận được sẽ bằng **tổng của tất cả các chữ số** cấu thành nên con số **N** đó. Ví dụ, nếu bốc được số `123`, người dân sẽ nhận được $1 + 2 + 3 = 6$ thỏi vàng.\n\nBạn hãy giúp các thần dân tính toán nhanh số lượng thỏi vàng mà họ sẽ nhận được từ con số may mắn của mình nhé!\n\n---\n## 📝 Đề bài\nCho một số nguyên dương **N**.  \nHãy tính tổng các chữ số của **N**.\n\n---\n## 📥 Dữ liệu vào\n- Một dòng duy nhất chứa số nguyên dương **N** ($1 \\le N \\le 10^{18}$).\n---\n## 📤 Dữ liệu ra\n- Một số nguyên duy nhất là tổng các chữ số của **N**.\n---\n## 📌 Ví dụ\n**Input**\n```\n1234\n```\n**Output**\n```\n10\n```','6',1000,262144,1,'2026-01-03 19:32:19',1),
(22,1,'KIỂM TRA SỐ NGUYÊN TỐ','## 📝 Đề bài\nCho một số nguyên dương **N**.  \nHãy kiểm tra xem **N có phải là số nguyên tố hay không**.\n\nMột số được gọi là **số nguyên tố** nếu:\n- Lớn hơn 1\n- Chỉ có đúng **hai ước số dương** là 1 và chính nó\n---\n## 📥 Dữ liệu vào\n- Một dòng duy nhất chứa số nguyên **N**\n---\n## 📤 Dữ liệu ra\n- In ra `YES` nếu **N là số nguyên tố**\n- In ra `NO` nếu **N không phải là số nguyên tố**\n---\n## 📌 Ví dụ\n### Input\n```\n11\n```\n### Output\n```\nYES\n```','8',1000,262144,1,'2026-01-03 19:32:55',1),
(23,1,'ĐẾM SỐ ÂM','## 📝 Đề bài\nCho một mảng số nguyên. Đếm số phần tử âm trong mảng.\n## 📥 Dữ liệu vào\n* Dòng 1: Số nguyên **n** (`1 ≤ n ≤ 10^5`)\n* Dòng 2: **n số nguyên** `a1, a2, ..., an`\n## 📤 Dữ liệu ra\n- Số lượng phần tử âm\n## 📌 Ví dụ\nInput:\n```\n5\n1 7 -3 9 -2\n```\nOutput:\n```\n2\n```','3',1000,262144,1,'2026-01-03 19:33:29',1),
(24,1,'ĐẾM SỐ LƯỢNG SỐ NGUYÊN TỐ TRONG MẢNG','## 📝 Đề bài\nCho một mảng gồm **n** số nguyên dương $a_1, a_2, ..., a_n$.  \nHãy đếm xem trong mảng có bao nhiêu số là **số nguyên tố**.\n\nMột số được gọi là **số nguyên tố** nếu:\n- Lớn hơn 1\n- Chỉ có đúng **hai ước số dương** là 1 và chính nó\n---\n\n## 📥 Dữ liệu vào\n- Dòng đầu tiên chứa số nguyên dương **n** (số lượng phần tử của mảng)\n- Dòng thứ hai chứa **n** số nguyên $a_1, a_2, ..., a_n$, mỗi số cách nhau một khoảng trắng\n---\n## 📤 Dữ liệu ra\n- Một số nguyên duy nhất là số lượng số nguyên tố có trong mảng\n---\n## 📌 Ví dụ\n**Input**\n```\n5\n2 3 4 5 10\n```\n**Output**\n```\n3\n```','9',1000,262144,1,'2026-01-03 19:33:59',1),
(25,2,'CHIA NGUYÊN','## 📝 Đề bài\nCho hai số nguyên A và B. Hãy tính giá trị chi nguyên của hai số đó.\n## 📥 Dữ liệu vào\n- Một dòng chứa hai số nguyên A, B\n## 📤 Dữ liệu ra\n- In ra phần nguyên A / B\n## 📌 Ví dụ\nInput:\n```\n5 3\n```\nOutput:\n```\n1\n```','1',1000,262144,1,'2026-01-03 19:34:23',1),
(26,2,'TỔNG HAI SỐ','## 📝 Đề bài\nCho hai số nguyên A và B. Hãy tính tổng của hai số đó.\n## 📥 Dữ liệu vào\n- Một dòng chứa hai số nguyên A, B\n## 📤 Dữ liệu ra\n- In ra tổng A + B\n## 📌 Ví dụ\nInput:\n```\n3 5\n```\nOutput:\n```\n8\n```','1',1000,262144,1,'2026-01-03 19:35:13',1),
(27,1,'TÍNH TỔNG CÁC SỐ ÂM TRONG MẢNG','## 📝 Đề bài\nCho một mảng gồm **n** số nguyên $a_1, a_2, ..., a_n$.  \nHãy tính tổng của tất cả các phần tử có giá trị **nhỏ hơn 0** (số âm) trong mảng đó.\n\n---\n## 📥 Dữ liệu vào\n- Dòng đầu tiên chứa số nguyên dương **n** (số lượng phần tử của mảng).\n- Dòng thứ hai chứa **n** số nguyên $a_1, a_2, ..., a_n$, mỗi số cách nhau một khoảng trắng.\n---\n## 📤 Dữ liệu ra\n- Một số nguyên duy nhất là tổng của các số âm trong mảng (nếu không có số âm nào, in ra 0).\n---\n## 📌 Ví dụ\n**Input**\n```\n5\n-2 5 -3 8 -1\n```\n**Output**\n```\n-6\n```','3',1000,262144,1,'2026-01-03 19:35:46',1),
(28,1,'TÍNH TỔNG CÁC SỐ LỚN HƠN K TRONG MẢNG','## 📝 Đề bài\n\nCho một mảng gồm **n** số nguyên dương $a_1, a_2, ..., a_n$ và một số nguyên **k**.  \nHãy tính tổng của tất cả các phần tử trong mảng có giá trị **lớn hơn k**.\n\n---\n## 📥 Dữ liệu vào\n- Dòng đầu tiên chứa hai số nguyên dương **n** và **k** cách nhau một khoảng trắng.\n- Dòng thứ hai chứa **n** số nguyên $a_1, a_2, ..., a_n$, mỗi số cách nhau một khoảng trắng.\n---\n## 📤 Dữ liệu ra\n- Một số nguyên duy nhất là tổng các số thỏa mãn điều kiện (nếu không có số nào lớn hơn k, in ra 0).\n---\n## 📌 Ví dụ\n**Input**\n```\n5 10\n5 12 8 20 15\n```\n**Output**\n```\n47\n```','5',1000,262144,1,'2026-01-03 19:36:17',1),
(29,1,'TÌM ƯỚC SỐ CHUNG LỚN NHẤT','## 📝 Đề bài\nCho hai số nguyên dương **a** và **b**.  \nHãy tìm **Ước số chung lớn nhất (ƯCLN)** của hai số đó.\n\nƯớc số chung lớn nhất của hai số nguyên là số nguyên dương lớn nhất mà cả hai số đó đều chia hết.\n\n---\n## 📥 Dữ liệu vào\n- Một dòng duy nhất chứa hai số nguyên dương **a** và **b**, cách nhau một khoảng trắng.\n---\n## 📤 Dữ liệu ra\n- Một số nguyên duy nhất là ước số chung lớn nhất của **a** và **b**.\n---\n## 📌 Ví dụ\n**Input**\n```\n12 18\n```\n**Output**\n```\n6\n```','7',1000,262144,1,'2026-01-03 19:36:46',1);
